  'A short walk through the platform, pointing at where everything is. Takes about two minutes and you can stop at any point.': 'Uma visita rápida à plataforma, a mostrar onde está tudo. Demora cerca de dois minutos e podes parar quando quiseres.',
  'A statement already counted this month. Ask the team to take it out.': 'Um extrato já contou este mês. Pede à equipa que o retire.',
  'A theme, a brief, hook ideas and a goal for each month. Every VIP in scope is told, sees it at the top of their month, and gets live standings.': 'Um tema, um briefing, ideias de gancho e um objetivo para cada mês. Todos os VIP abrangidos são avisados, veem-no no topo do seu mês e têm uma classificação em direto.',
