  'A video counts if it is public, posted on your own account within the last {days} days, and mentions or tags Tryp.com as agreed with the team. Reposts of an earlier video do not count.': 'Um vídeo conta se for público, publicado na tua própria conta nos últimos {days} dias e mencionar ou marcar a Tryp.com como combinado com a equipa. Republicações de um vídeo anterior não contam.',
