  'Approve all {n}': 'Aprovar os {n}',
  'Approve all {n} drafts? Each one is added to the creator\'s balance, and their payout window opens.': 'Aprovar os {n} rascunhos? Cada um é somado ao saldo do criador e abre-se o prazo de pagamento.',
  'Approve all {n} drafts? Each one raises its invoice for the creator. You can still stop an invoice from Rewards.': 'Aprovar os {n} rascunhos? Cada um gera a fatura do criador. Ainda podes parar uma fatura em Recompensas.',
  'Approved': 'Aprovados',
  'Approved, to pay': 'Aprovada, por pagar',
  'Approving a month adds it to each balance. For {d} days after the month ends, a VIP can take cash (from {a}) or a Tryp.com voucher (any amount). Otherwise it keeps growing.': 'Aprovar um mês soma-o a cada saldo. Durante {d} dias após o fim do mês, um VIP pode receber em dinheiro (a partir de {a}) ou um voucher Tryp.com (qualquer valor). Caso contrário, continua a crescer.',
  'Approving a statement adds it to the creator\'s balance and opens their payout window: cash once the balance reaches the threshold, or a Tryp.com voucher for any amount. Their invoice is raised when they ask for cash. Late corrections go on next month\'s statement or as a balance correction in Balances.': 'Aprovar um extrato soma-o ao saldo do criador e abre o prazo de pagamento: dinheiro quando o saldo atinge o mínimo, ou um voucher Tryp.com de qualquer valor. A fatura é emitida quando pede o dinheiro. Correções tardias vão no extrato do mês seguinte ou como correção de saldo em Saldos.',
  'Approving a statement raises the creator\'s invoice and counts as approving it. A creator with no payment details is approved anyway and their invoice follows the day they save them. Late corrections go on next month\'s statement, never by reopening a month that is paid.': 'Aprovar um extrato gera a fatura do criador e conta como aprová-la. Um criador sem dados de pagamento é aprovado na mesma e a fatura segue no dia em que os guardar. As correções tardias vão no extrato do mês seguinte, nunca reabrindo um mês pago.',
