  'At the end of each month we take a final reading of your views, draft your statement and, once it is approved, your invoice.': 'No fim de cada mês fazemos uma leitura final das tuas visualizações, preparamos o teu extrato e, depois de aprovado, a tua fatura.',
  'At the end of each month we take a final reading of your views, draft your statement and, once it is approved, your invoice. Small amounts below the minimum payout carry over to the next month.': 'No fim de cada mês fazemos uma leitura final das tuas visualizações, redigimos o teu extrato e, depois de aprovado, a tua fatura. Os valores pequenos abaixo do pagamento mínimo transitam para o mês seguinte.',
