  'I make short travel videos about the places I go and the things worth stopping for. I am part of the Tryp.com Content Creator Community, where creators from around the world make work for monthly challenges.': 'Faço vídeos curtos de viagens sobre os sítios onde vou e o que vale a pena ver. Faço parte da Tryp.com Content Creator Community, onde criadores de todo o mundo criam conteúdo para desafios mensais.',
  'I\'ll do this later': 'Faço isto mais tarde',
  'I\'m in Lisbon the same week. Fancy shooting a couple of reels around Alfama, or just a coffee?': 'Estou em Lisboa nessa mesma semana. Apetece-te gravar uns reels por Alfama, ou só um café?',
  'I\'m planning a Balkans road trip next spring and would love to team up with anyone heading that way.': 'Estou a planear uma viagem pelos Balcãs na próxima primavera e adorava juntar-me a quem for para lá.',
  'Identity': 'Identidade',
  'If an account exists for {email}, you\'ll receive a reset link shortly. Check your spam folder too.': 'Se existir uma conta para {email}, vais receber em breve um link para repor a palavra-passe. Vê também a pasta de spam.',
  'If it keeps failing, please let us know rather than waiting.': 'Se continuar a falhar, avisa-nos em vez de esperares.',
  'If it still will not read, try the digital pass instead: a screenshot straight from Apple Wallet or the airline app scans far more reliably than a photo of a printed one. Otherwise close this and type the flight in.': 'Se continuar sem ler, usa antes o cartão digital: uma captura direta da Apple Wallet ou da app da companhia é lida com muito mais fiabilidade do que a foto de um impresso. Caso contrário, fecha isto e escreve o voo à mão.',
  'If the month ended now: {n} would earn it, {a} in all.': 'Se o mês terminasse agora: ganhariam {n}, {a} no total.',
  'If you win before we have these, your prize waits until we do. You can add them any time from Settings.': 'Se ganhares antes de termos estes dados, o teu prémio fica à espera. Podes adicioná-los a qualquer momento nas Definições.',
