  'One link for every VIP, in every market. They sign up as usual, are marked as VIPs in the applications list, and are placed with their own market\'s VIP programme when you approve them.': 'Um único link para todos os VIP, em todos os mercados. Registam-se como de costume, aparecem marcados como VIP na lista de candidaturas e, quando os aprovas, ficam no programa VIP do seu próprio mercado.',
