  'Only admins see this preview. Each one uses your name and a sample challenge; open one to check the certificate, the Instagram story and both downloads. Drafts are not given to anybody.': 'Só os administradores veem esta pré-visualização. Cada um usa o teu nome e um desafio de exemplo; abre um para verificar o certificado, a story do Instagram e as duas transferências. Os rascunhos não são entregues a ninguém.',
