  'Only TikTok, Instagram, YouTube and Facebook links carry a view count we can read.': 'Só os links do TikTok, Instagram, YouTube e Facebook trazem uma contagem de visualizações que conseguimos ler.',
  'Only VIP creators and the team can see these. Ask anything, share what is working, and meet the other VIPs.': 'Só os criadores VIP e a equipa as podem ver. Pergunta o que quiseres, partilha o que funciona e conhece os outros VIP.',
  'Only VIP creators and the team can see these. This is where the WhatsApp group lives now.': 'Só os criadores VIP e a equipa as podem ver. É aqui que vive agora o grupo de WhatsApp.',
  'Only you can see these': 'Só tu vês isto',
