  'Turn them back on in Settings → Notifications → Tryp.com (iPhone), or by pressing the padlock beside the address bar and allowing notifications (browser).': 'Volta a ligá-las em Definições → Notificações → Tryp.com (iPhone), ou carregando no cadeado ao lado da barra de endereço e permitindo notificações (navegador).',
