  'We are all in the community. Press a name to open a private chat.': 'Estamos todos na comunidade. Carrega num nome para abrir uma conversa privada.',
  'We are in the community too. Connect or message any of us.': 'Também estamos na comunidade. Liga-te ou escreve a qualquer um de nós.',
  'We cannot ask again from here once a device has said no.': 'Depois de um dispositivo dizer que não, já não podemos voltar a perguntar a partir daqui.',
  'We cannot pay your monthly invoice until they are saved.': 'Não podemos pagar a tua fatura mensal até estarem guardados.',
  'We could not find a free web address for that name. Try a different one in Advanced.': 'Não encontrámos um endereço livre para esse nome. Experimenta outro em Avançado.',
  'We could not read a preview. Your entry still counts.': 'Não conseguimos carregar uma pré-visualização. A tua participação conta na mesma.',
  'We did not get a session back. That usually means the link was opened twice or it has expired.': 'Não recebemos nenhuma sessão. Normalmente significa que o link foi aberto duas vezes ou que expirou.',
  'We do not recognise that VIP link. Check you copied all of it, or ask the team to send it again. You can still sign up as a creator below.': 'Não reconhecemos essa ligação VIP. Verifica se a copiaste toda ou pede à equipa que a envie de novo. Ainda podes registar-te como criador abaixo.',
  'We email a reset link to the address above.': 'Enviamos um link de recuperação para o endereço acima.',
  'We filled in what your profile already says. Answer what you like, and your card builds itself as you go.': 'Preenchemos o que o teu perfil já diz. Responde ao que quiseres — o teu cartão vai-se construindo sozinho.',
  'We filled in what your profile already says. Change anything, skip anything, and your card is ready.': 'Preenchemos o que o teu perfil já diz. Muda o que quiseres, salta o que quiseres, e o teu cartão fica pronto.',
  'We have sent you a confirmation link. Open it, then log in and we will take you through the rest.': 'Enviámos-te um link de confirmação. Abre-o, inicia sessão e levamos-te pelo resto.',
  'We have your age as {n}. Add your date of birth and it will stay right on your birthday.': 'Temos a tua idade como {n}. Acrescenta a data de nascimento e fica certa também no teu aniversário.',
  'We post new positions here first. Keep creating great content and you\'ll be top of mind.': 'Publicamos aqui primeiro as novas vagas. Continua a fazer bom conteúdo e serás dos primeiros em quem pensamos.',
  'We want your ideas for challenges, features and anything else.': 'Queremos as tuas ideias para desafios, funcionalidades e tudo o resto.',
  'We\'re having trouble reaching the server. Your connection might be slow. Give it another try.': 'Estamos com dificuldade em chegar ao servidor. A tua ligação pode estar lenta. Tenta outra vez.',
  'Weak signal: loading the essentials first': 'Sinal fraco: a carregar primeiro o essencial',
