  'You are in the prize places, so this one goes to someone else.': 'Estás nos lugares premiados, por isso este vai para outra pessoa.',
  'You are in the worldwide community as well. A market is where your briefs come from, not a smaller room you go into instead.': 'Também estás na comunidade mundial. Um mercado é de onde vêm os teus briefings, não uma sala mais pequena para onde vais em vez disso.',
  'You are in these.': 'Estás nestes.',
  'You are joining the Tryp.com Content Creator Community, a global community of travel creators who make great content, compete in challenges and earn real rewards.': 'Estás a entrar na Tryp.com Content Creator Community, uma comunidade mundial de criadores de viagens que fazem bom conteúdo, competem em challenges e ganham prémios a sério.',
  'You are joining the VIP creators': 'Vais juntar-te aos criadores VIP',
  'You are left out of the public map, the creators strip and the wall of fame. Fellow creators can still find you in the app.': 'Ficas de fora do mapa público, da faixa de criadores e da galeria dos melhores. Os outros criadores continuam a encontrar-te na app.',
  'You are looking at {p}. You can see everything here, but only its own lead can change it.': 'Estás a ver {p}. Podes ver tudo, mas só o seu responsável o pode alterar.',
  'You are looking at this the way the creator sees it. Nothing here can be edited by you.': 'Estás a ver isto tal como o criador o vê. Não podes editar nada aqui.',
  'You are not on the board yet. Play any travel game today and you will be tomorrow.': 'Ainda não estás no quadro. Joga hoje qualquer jogo de viagens e amanhã já estás.',
  'You are paid by the views your videos bring. Add your first video to start your month.': 'Recebes pelas visualizações que os teus vídeos trazem. Adiciona o teu primeiro vídeo para começar o mês.',
  'You are paid for the views your videos gain during each calendar month, at the rate on your VIP page. Views from before you added a video, or from before the month began, are not counted.': 'És pago pelas visualizações que os teus vídeos ganham em cada mês civil, à tarifa da tua página VIP. As visualizações de antes de adicionares um vídeo, ou de antes de o mês começar, não contam.',
  'You are reading this the way the creator sees it. Only they can change what it says.': 'Estás a ler isto tal como o criador o vê. Só ele pode mudar o que aqui está.',
