  'You could be the first to explore it. Add it to your travels once you go, and the next creator planning this trip will find you here.': 'Podes ser o primeiro a explorá-lo. Acrescenta-o às tuas viagens quando lá fores e o próximo criador a planear esta viagem encontra-te aqui.',
